using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> L(N);
    long long S = 0;
    for (int i = 0; i < N; i++) {
        cin >> L[i];
        S += L[i];
    }

    if (S % 2 != 0) {
        cout << 'N' << '\n';
        return 0;
    }

    long long half = S / 2;
    vector<long long> pos(N);
    long long cur = 0;
    for (int i = 0; i < N; i++) {
        pos[i] = cur;
        cur += L[i];
    }

    int cnt = 0;
    for (int i = 0; i < N; i++) {
        long long q = pos[i] + half;
        if (q >= S) q -= S;
        if (binary_search(pos.begin(), pos.end(), q)) {
            cnt++;
        }
    }

    if (cnt / 2 >= 2) {
        cout << 'S' << '\n';
    } else {
        cout << 'N' << '\n';
    }

    return 0;
}
